declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';$user=require_role('donor');$pledgeId=filter_input(INPUT_GET,'pledge',FILTER_VALIDATE_INT);if(!$pledgeId){http_response_code(404);exit('Certificate not found.');}$pdo=db();$stmt=$pdo->prepare("SELECT dp.*,u.name donor_name,c.organization_name,cr.title,COALESCE(SUM(di.quantity),0) items FROM donation_pledges dp JOIN users u ON u.id=dp.donor_id JOIN clothing_requests cr ON cr.id=dp.request_id JOIN charities c ON c.id=cr.charity_id LEFT JOIN donation_items di ON di.pledge_id=dp.id WHERE dp.id=? AND dp.donor_id=? AND dp.status='received' GROUP BY dp.id");$stmt->execute([$pledgeId,$user['id']]);$donation=$stmt->fetch();if(!$donation){http_response_code(404);exit('Certificates are available after a donation is confirmed.');}$number='GFT-'.date('Y').'-'.str_pad((string)$pledgeId,6,'0',STR_PAD_LEFT);$insert=$pdo->prepare('INSERT IGNORE INTO donation_certificates (pledge_id,certificate_number) VALUES (?,?)');$insert->execute([$pledgeId,$number]);$esc=static function(string $value):string{$value=iconv('UTF-8','Windows-1252//TRANSLIT',$value)?:$value;return str_replace(['\\','(',')'],['\\\\','\\(','\\)'],$value);};$lines=['GIFTLY','Certificate of Donation','This celebrates '. $donation['donor_name'].' for a confirmed clothing donation.','Charity: '.$donation['organization_name'],'Request: '.$donation['title'],'Confirmed items: '.$donation['items'],'Date confirmed: '.format_date($donation['updated_at']),'Certificate no. '.$number,'Thank you for giving useful clothes their next chapter.'];$y=755;$content='BT /F1 26 Tf 54 790 Td 0.94 0.27 0.15 rg (GIFTLY) Tj ET ';foreach($lines as $index=>$line){$size=$index===1?22:($index===0?10:13);$color=$index===1?'0.13 0.13 0.12':'0.20 0.20 0.18';$content.='BT /F1 '.$size.' Tf '.$color.' rg 54 '.$y.' Td ('.$esc($line).') Tj ET ';$y-=($index===1?45:28);}$stream=$content;$pdf="%PDF-1.4\n1 0 obj<< /Type /Catalog /Pages 2 0 R >>endobj\n2 0 obj<< /Type /Pages /Kids [3 0 R] /Count 1 >>endobj\n3 0 obj<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>endobj\n4 0 obj<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>endobj\n5 0 obj<< /Length ".strlen($stream)." >>stream\n$stream\nendstream\nendobj\n";$offsets=[0,9,58,115,246,316];$xref=strlen($pdf);$pdf.="xref\n0 6\n0000000000 65535 f \n";foreach(array_slice($offsets,1) as $offset)$pdf.=sprintf('%010d 00000 n ',$offset)."\n";$pdf.="trailer<< /Size 6 /Root 1 0 R >>\nstartxref\n$xref\n%%EOF";header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="giftly-certificate-'.$pledgeId.'.pdf"');header('Content-Length: '.strlen($pdf));echo $pdf;exit;
